$ErrorActionPreference = 'Stop'
$siteRoot = Split-Path -Parent $MyInvocation.MyCommand.Path

function Nav([string]$active) {
  $items = @(
    @('Pealeht','/','home'),
    @('Meist','/meist/','meist'),
    @('Tooted','/tooted/','tooted'),
    @('Galerii','/galerii/','galerii'),
    @('Tellimuskeskus','/hinnaparing/','quote'),
    @('Kontakt','/kontakt/','kontakt')
  )
  $productActives = @('tooted','lepp','saun','termo')
  $links = ($items | ForEach-Object { $selected = ($_[2] -eq $active) -or ($_[2] -eq 'tooted' -and $active -in $productActives); $current = if ($selected) {' aria-current="page"'} else {''}; "<a href='$($_[1])'$current>$($_[0])</a>" }) -join "`n"
  return "<header class='site-header'><a class='skip' href='#sisu'>Liigu sisu juurde</a><div class='wrap nav'><a class='brand' href='/' aria-label='Servamatapuit avaleht'><img src='/assets/servamatapuit-logo-tight.png' alt='Servamatapuit'></a><button class='mobile-toggle' aria-label='Ava menüü' aria-expanded='false'>☰</button><nav class='menu' aria-label='Peamenüü'>$links</nav></div></header>"
}

function Footer {
  return @"
<footer class='footer'><div class='wrap footer-line'><span>Copyright © 2026 Servamatapuit.ee</span><span><a href='/kontakt/'>Kontakt</a> · <a href='/privaatsus/'>Privaatsus ja küpsised</a></span></div></footer><script src='/assets/site.js' defer></script>
"@
}

function Page([string]$slug,[string]$title,[string]$description,[string]$active,[string]$body) {
  $dir = if ($slug -eq '') {$siteRoot} else {Join-Path $siteRoot $slug}
  New-Item -ItemType Directory -Force -Path $dir | Out-Null
  $canonical = if ($slug -eq '') {'https://servamatapuit.ee/'} else {"https://servamatapuit.ee/$slug/"}
  $html = @"
<!doctype html><html lang='et'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='google-site-verification' content='ieFCUeWB4pUqxDX980S_COd47kW6NTU7FPkbfUWJFUU'><meta name='referrer' content='strict-origin-when-cross-origin'><title>$title</title><meta name='description' content='$description'><link rel='canonical' href='$canonical'><meta property='og:title' content='$title'><meta property='og:description' content='$description'><meta property='og:type' content='website'><meta property='og:url' content='$canonical'><meta property='og:image' content='https://servamatapuit.ee/assets/oksavaba-servamata-lepp.jpg'><script type='application/ld+json'>{"@context":"https://schema.org","@graph":[{"@type":"WebSite","@id":"https://servamatapuit.ee/#website","url":"https://servamatapuit.ee/","name":"Servamatapuit","inLanguage":"et"},{"@type":"LocalBusiness","@id":"https://servamatapuit.ee/#business","name":"Strumest OÜ – Servamatapuit","url":"https://servamatapuit.ee/","logo":"https://servamatapuit.ee/assets/servamatapuit-logo-tight.png","image":"https://servamatapuit.ee/assets/oksavaba-servamata-lepp.jpg","telephone":"+37255523176","email":"strumest@hotmail.com","priceRange":"€€","address":{"@type":"PostalAddress","streetAddress":"Saekaatri","addressLocality":"Taganurga","addressRegion":"Viljandi maakond","addressCountry":"EE"}}]}</script><link rel='icon' href='/assets/servamatapuit-logo-tight.png'><link rel='stylesheet' href='/assets/style.css'></head><body>$(Nav $active)<main id='sisu'>$body</main>$(Footer)</body></html>
"@
  Set-Content -LiteralPath (Join-Path $dir 'index.html') -Value $html -Encoding utf8
}

$homeBody = @"
<section class='legacy-hero'><div class='legacy-overlay'></div><div class='wrap legacy-hero-content'><h1>Servamatapuit</h1><p>Pakume kvaliteetseid <strong>servamata lepalauamaterjale</strong>, <strong>profiillaudu</strong> ning <strong>termotöödeldud puidutooteid</strong> ehituse ja sisekujunduse tarbeks. Meie eesmärk on tuua <strong>Eesti looduslähedane ilu</strong> igasse ruumi, hoonesse või aeda.</p><a class='legacy-button' href='/kontakt/'>Kontakt</a></div><div class='pyramid bottom'></div></section>

