function ProductPage([string]$slug,[string]$title,[string]$intro,[string]$image,[string]$alt,[string]$active,[string]$table,[string]$extra) {
  $body = "<section class='hero'><div class='wrap hero-grid'><div><span class='eyebrow'>Tooted</span><h1>$title</h1><p class='lead'>$intro</p><div class='actions'><a class='btn' href='/hinnaparing/'>Küsi saadavust ja hinda</a></div></div><div class='hero-media'><img src='/assets/$image' alt='$alt'></div></div></section><section class='section'><div class='wrap content'><div class='prose'>$extra<div class='table-wrap'>$table</div><div class='notice'>Puit on looduslik materjal ning toon, laius ja struktuur võivad partiiti erineda. Täpse saadavuse kinnitame pakkumises.</div></div><aside class='sidebox'><h3>Küsi pakkumist</h3><p>Lisa mõõt, kogus ja tarnekoht. Nii saame teha täpse pakkumise.</p><a class='btn' href='/hinnaparing/'>Saada päring</a></aside></div></section>"
  Page $slug "$title | Servamatapuit" $intro $active $body
}

