$xml = "<?xml version='1.0' encoding='UTF-8'?>`n<urlset xmlns='http://www.sitemaps.org/schemas/sitemap/0.9'>`n" + (($urls | ForEach-Object { $loc = if ($_ -eq '') {'https://servamatapuit.ee/'} else {"https://servamatapuit.ee/$_/"}; "  <url><loc>$loc</loc></url>" }) -join "`n") + "`n</urlset>"
